#include <boost/multiprecision/cpp_int.hpp>

#include <stdexcept>
#include <string>

// Prices and rates are intentionally accepted as strings.  This keeps input
// decimal values exact all the way through the one required rounding step.
class CheckoutPriceCalculator
{
public:
    enum class ShippingMethod
    {
        Standard,
        Expedited
    };

    // Rates are fractions: for example, "0.1" represents ten percent.
    std::string calculate(const std::string& itemPrice,
                          const std::string& discountRate,
                          const std::string& taxRate,
                          ShippingMethod shipping) const
    {
        const Decimal price = parseDecimal(itemPrice, "item price");
        const Decimal discount = parseDecimal(discountRate, "discount rate");
        const Decimal tax = parseDecimal(taxRate, "tax rate");

        requireRate(discount, "discount rate");
        requireRate(tax, "tax rate");

        // (price * (1 - discount) + shipping) * (1 + tax)
        const Integer subtotalNumerator =
            price.numerator * (discount.denominator - discount.numerator) +
            (shipping == ShippingMethod::Expedited ? Integer(1500) : Integer(0)) *
                price.denominator * discount.denominator;
        const Integer subtotalDenominator = price.denominator * discount.denominator;

        const Integer totalNumerator = subtotalNumerator *
                                       (tax.denominator + tax.numerator);
        const Integer totalDenominator = subtotalDenominator * tax.denominator;

        return formatCents(roundToCents(totalNumerator, totalDenominator));
    }

    // A convenience overload for callers whose shipping choice is a boolean.
    std::string calculate(const std::string& itemPrice,
                          const std::string& discountRate,
                          const std::string& taxRate,
                          bool expeditedShipping) const
    {
        return calculate(itemPrice, discountRate, taxRate,
                         expeditedShipping ? ShippingMethod::Expedited
                                            : ShippingMethod::Standard);
    }

private:
    using Integer = boost::multiprecision::cpp_int;

    struct Decimal
    {
        Integer numerator;
        Integer denominator;
    };

    static Decimal parseDecimal(const std::string& value, const char* field)
    {
        if (value.empty())
            throw std::invalid_argument(std::string(field) + " must not be empty");

        bool seenPoint = false;
        std::size_t fractionDigits = 0;
        Integer numerator = 0;

        for (std::size_t i = 0; i < value.size(); ++i)
        {
            const char ch = value[i];
            if (ch == '.')
            {
                if (seenPoint || i == 0 || i + 1 == value.size())
                    throw std::invalid_argument(std::string(field) + " is not a plain decimal");
                seenPoint = true;
                continue;
            }
            if (ch < '0' || ch > '9')
                throw std::invalid_argument(std::string(field) + " is not a plain decimal");

            numerator *= 10;
            numerator += ch - '0';
            if (seenPoint)
                ++fractionDigits;
        }

        Integer denominator = 1;
        for (std::size_t i = 0; i < fractionDigits; ++i)
            denominator *= 10;
        return {numerator, denominator};
    }

    static void requireRate(const Decimal& rate, const char* field)
    {
        if (rate.numerator > rate.denominator)
            throw std::invalid_argument(std::string(field) + " must be in [0, 1]");
    }

    static Integer roundToCents(const Integer& numerator, const Integer& denominator)
    {
        const Integer scaled = numerator * 100;
        Integer cents = scaled / denominator;
        const Integer remainder = scaled % denominator;
        const Integer twiceRemainder = remainder * 2;

        // At an exact half, retain an even number of cents.
        if (twiceRemainder > denominator ||
            (twiceRemainder == denominator && (cents & 1) != 0))
            ++cents;
        return cents;
    }

    static std::string formatCents(const Integer& cents)
    {
        const Integer dollars = cents / 100;
        const unsigned int pennies = (cents % 100).convert_to<unsigned int>();
        return dollars.convert_to<std::string>() + "." +
               (pennies < 10 ? "0" : "") + std::to_string(pennies);
    }
};

