        int borrow = 0;
        for (std::size_t i = 0; i < left.size(); ++i)
        {
            int a = left[left.size() - 1 - i] - '0' - borrow;
            const int b = i < right.size() ? right[right.size() - 1 - i] - '0' : 0;
