                (firstDiscarded == '5' && (laterDiscardedNonzero || (cents.back() - '0') % 2 != 0)))
                increment(cents);
        }

        cents = stripLeadingZeros(cents);
        if (cents.size() == 1) cents.insert(cents.begin(), '0');
        return cents.substr(0, cents.size() - 2) + "." + cents.substr(cents.size() - 2);
    }
};

