#include <cassert>
#include <stdexcept>
#include \"CheckoutPriceCalculator.cpp\"

int main() {
    CheckoutPriceCalculator calculator;
    using Shipping = CheckoutPriceCalculator::ShippingMethod;
    assert(calculator.calculate(\"100\", \"0.1\", \"0.05\", Shipping::Standard) == \"94.50\");
    assert(calculator.calculate(\"100\", \"0.1\", \"0.05\", Shipping::Expedited) == \"110.25\");
    assert(calculator.calculate(\"0.005\", \"0\", \"0\", false) == \"0.00\");
    assert(calculator.calculate(\"0.015\", \"0\", \"0\", false) == \"0.02\");
    assert(calculator.calculate(\"0.025\", \"0\", \"0\", false) == \"0.02\");
    assert(calculator.calculate(\"0.035\", \"0\", \"0\", false) == \"0.04\");
    assert(calculator.calculate(\"10\", \"1\", \"0\", false) == \"0.00\");
    assert(calculator.calculate(\"0\", \"0\", \"0\", true) == \"15.00\");
    try { calculator.calculate(\"10\", \"1.01\", \"0\", false); assert(false); }
    catch (const std::invalid_argument&) {}
}
EOF
